from models import get_db
import sqlite3

bp = Blueprint('api', __name__, url_prefix='/api')

# ---------------------------------------------------------------------------
# Helper utilities
# ---------------------------------------------------------------------------

def _row_to_dict(row):
    """Convert a sqlite3.Row to a plain dict."""
    return dict(row) if isinstance(row, sqlite3.Row) else row

def _validate_task_data(data, partial=False):
    required = ['title', 'status', 'due_date', 'assigned_user_id']
    missing = []
    for field in required:
        if not partial or field in data:
            if field not in data:
                missing.append(field)
    if missing:
        abort(400, description=f"Missing required fields: {', '.join(missing)}")
    # type checks (basic)
    if 'assigned_user_id' in data and not isinstance(data['assigned_user_id'], int):
        abort(400, description='assigned_user_id must be integer')

def _validate_user_data(data, partial=False):
    required = ['username', 'email']
    missing = []
    for field in required:
        if not partial or field in data:
            if field not in data:
                missing.append(field)
    if missing:
        abort(400, description=f"Missing required fields: {', '.join(missing)}")

# ---------------------------------------------------------------------------
# Task endpoints
# ---------------------------------------------------------------------------

@bp.route('/tasks', methods=['GET'])
def list_tasks():
    db = get_db()
    db.row_factory = sqlite3.Row
    tasks = db.execute('SELECT * FROM task').fetchall()
    return jsonify({"success": True, "data": [_row_to_dict(t) for t in tasks]})

@bp.route('/tasks/<int:item_id>', methods=['GET'])
def get_task(item_id):
    db = get_db()
    db.row_factory = sqlite3.Row
    task = db.execute('SELECT * FROM task WHERE id = ?', (item_id,)).fetchone()
    if task is None:
        abort(404, description='Task not found')
    return jsonify({"success": True, "data": _row_to_dict(task)})

@bp.route('/tasks', methods=['POST'])
def create_task():
    if not request.is_json:
        abort(400, description='Request must be JSON')
    data = request.get_json()
    _validate_task_data(data)
    db = get_db()
    cursor = db.execute(
        '''INSERT INTO task (title, description, status, due_date, assigned_user_id)
           VALUES (?, ?, ?, ?, ?)''',
        (
            data.get('title'),
            data.get('description'),
            data.get('status'),
            data.get('due_date'),
            data.get('assigned_user_id'),
        ),
    )
    db.commit()
    return jsonify({"success": True, "data": {"id": cursor.lastrowid}}), 201

@bp.route('/tasks/<int:item_id>', methods=['PUT'])
def update_task(item_id):
    if not request.is_json:
        abort(400, description='Request must be JSON')
    data = request.get_json()
    _validate_task_data(data, partial=False)
    db = get_db()
    cursor = db.execute(
        '''UPDATE task SET title = ?, description = ?, status = ?, due_date = ?, assigned_user_id = ?
           WHERE id = ?''',
        (
            data.get('title'),
            data.get('description'),
            data.get('status'),
            data.get('due_date'),
            data.get('assigned_user_id'),
            item_id,
        ),
    )
    db.commit()
    if cursor.rowcount == 0:
        abort(404, description='Task not found')
    return jsonify({"success": True, "data": {"id": item_id}})

@bp.route('/tasks/<int:item_id>', methods=['DELETE'])
def delete_task(item_id):
    db = get_db()
    cursor = db.execute('DELETE FROM task WHERE id = ?', (item_id,))
    db.commit()
    if cursor.rowcount == 0:
        abort(404, description='Task not found')
    return jsonify({"success": True, "data": {"id": item_id}})

